package assignment_28_09;

public class ASCII_code {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		char chA = 'A';
		char cha = 'a' ;
		char ch0 = '0';
		char chAt = '@';
		
		// cast char to ascii
		
		int asciiA = (int) chA;
		int asciia = (int) cha;
		int ascii0 = (int) ch0;
		int asciiAt = (int) chAt;
		
		System.out.println("Value of A :"+ asciiA);
		System.out.println("Value of a :"+ asciia);
		System.out.println("Value of 0 :"+ ascii0);
		System.out.println("Value of At :"+ asciiAt);
	}

}
